-- typical Supabase / Lovable migration
create table if not exists public.profiles (
  id uuid references auth.users not null primary key,
  username text unique,
  "Display Name" text,
  updated_at timestamp with time zone default now()
);
alter table public.profiles enable row level security;
create policy "Public profiles are viewable by everyone." on public.profiles
  for select using ( true );
create policy "Users can update own profile." on profiles
  for update to authenticated using ( (select auth.uid()) = id ) with check ( auth.uid() = id );
create table public.messages (id bigint generated by default as identity primary key, body text, user_id uuid);
alter table "public"."messages" disable row level security;
alter table only public.messages force row level security;
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
begin
  insert into public.profiles (id, username) values (new.id, new.raw_user_meta_data->>'username');
  return new;
end;
$$;
create function public.is_admin() returns boolean language sql security definer as $fn$ select true; $fn$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create view public.public_msgs with (security_invoker = on) as select id, body from public.messages;
create view public.all_msgs as select * from public.messages;
grant select on public.messages to anon, authenticated;
do $$ begin perform 1; end $$;
drop policy if exists "Public profiles are viewable by everyone." on public.profiles;
create policy "anyone can insert" on public.messages as permissive for insert to anon with check (true);
